using System.Security.Claims;using System.Text.Json;using DraftDatastore.Persistence;using Microsoft.EntityFrameworkCore;
namespace DraftDatastore.API.Middleware;
public sealed class AuditLoggingMiddleware(RequestDelegate next,ILogger<AuditLoggingMiddleware> logger){public async Task InvokeAsync(HttpContext context,DraftDatastoreDbContext db){await next(context);if(context.Response.StatusCode<400 && context.User.Identity?.IsAuthenticated==true && context.Request.Method is not "GET") {var id=context.User.FindFirstValue(ClaimTypes.NameIdentifier);db.AuditLogs.Add(new(){UserId=Guid.TryParse(id,out var userId)?userId:null,Action=context.Request.Method,EntityName=context.Request.Path.Value??"",EntityId="",OccurredAtUtc=DateTimeOffset.UtcNow,CorrelationId=context.TraceIdentifier,ChangesJson=JsonSerializer.Serialize(new{context.Response.StatusCode})});try{await db.SaveChangesAsync(context.RequestAborted);}catch(Exception ex){logger.LogError(ex,"Audit persistence failed. TraceId: {TraceId}",context.TraceIdentifier);}}}}
